package cn.zhuatech.traceability;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.*;import java.util.regex.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.httpBasic;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class DeepTraceOpsTests{@Autowired MockMvc mvc;
 @Test void qualityGenealogyEventAndRecallFormClosedLoop()throws Exception{long raw=batch("RAW-1","RAW",100);pass(raw,"QI-1");admin("/api/admin/trace-ops/batches/"+raw+"/release","{}");long finished=batch("FG-1","FINISHED",80);post("/api/trace-ops/genealogy","{\"sourceBatchId\":"+raw+",\"targetBatchId\":"+finished+",\"consumedQuantity\":80,\"processStep\":\"混配生产\"}");pass(finished,"QI-2");admin("/api/admin/trace-ops/batches/"+finished+"/release","{}");post("/api/trace-ops/batches/"+finished+"/events","{\"eventId\":\"EV-T-1\",\"eventType\":\"SHIPMENT\",\"location\":\"上海成品仓\",\"businessRef\":\"DN-1001\",\"occurredAt\":\"2026-09-02T10:00:00\"}");long r=id(post("/api/trace-ops/recalls","{\"recallNo\":\"RC-1\",\"sourceBatchId\":"+raw+",\"level\":\"LEVEL_1\",\"reason\":\"原料风险模拟召回\"}").andExpect(jsonPath("$.data.affectedBatchCount").value(2)).andReturn());post("/api/trace-ops/recalls/"+r+"/notify","{}");admin("/api/admin/trace-ops/recalls/"+r+"/close","{}").andExpect(jsonPath("$.data.status").value("CLOSED"));}
 @Test void releaseAndQuantityGatesAreEnforced()throws Exception{long raw=batch("RAW-2","RAW",10);admin("/api/admin/trace-ops/batches/"+raw+"/release","{}").andExpect(status().isConflict());pass(raw,"QI-3");admin("/api/admin/trace-ops/batches/"+raw+"/release","{}");long out=batch("FG-2","FINISHED",10);post("/api/trace-ops/genealogy","{\"sourceBatchId\":"+raw+",\"targetBatchId\":"+out+",\"consumedQuantity\":11,\"processStep\":\"超量投入\"}").andExpect(status().isConflict());}
 @Test void quarantineCannotShipAndRecallMustNotifyBeforeClose()throws Exception{long b=batch("FG-3","FINISHED",20);post("/api/trace-ops/batches/"+b+"/events","{\"eventId\":\"EV-BAD\",\"eventType\":\"SHIPMENT\",\"location\":\"仓库\",\"businessRef\":\"DN-X\",\"occurredAt\":\"2026-09-02T10:00:00\"}").andExpect(status().isConflict());long r=id(post("/api/trace-ops/recalls","{\"recallNo\":\"RC-3\",\"sourceBatchId\":"+b+",\"level\":\"LEVEL_2\",\"reason\":\"演练\"}").andReturn());admin("/api/admin/trace-ops/recalls/"+r+"/close","{}").andExpect(status().isConflict());}
 long batch(String n,String t,double q)throws Exception{return id(post("/api/trace-ops/batches","{\"organizationCode\":\"ZH-SH\",\"batchNo\":\""+n+"\",\"materialCode\":\"MAT-100\",\"batchType\":\""+t+"\",\"quantity\":"+q+",\"productionDate\":\"2026-09-01\",\"expiryDate\":\"2027-09-01\"}").andReturn());}void pass(long b,String n)throws Exception{post("/api/trace-ops/batches/"+b+"/inspections","{\"inspectionNo\":\""+n+"\",\"result\":\"PASSED\",\"conclusion\":\"检验合格\",\"inspector\":\"质检员\"}");}ResultActions post(String u,String b)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(u).with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content(b));}ResultActions admin(String u,String b)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(u).with(httpBasic("admin","admin123")).contentType(MediaType.APPLICATION_JSON).content(b));}long id(MvcResult r)throws Exception{var m=Pattern.compile("\"id\":(\\d+)").matcher(r.getResponse().getContentAsString());Assertions.assertTrue(m.find());return Long.parseLong(m.group(1));}}
